    const w = cross(deviations);
    for (let i = 0; i < p; i++) for (let j = 0; j < p; j++) within[i]![j]! += w[i]![j]!;
    const d = means[k]!.map((v, j) => v - center[j]!);
    for (let i = 0; i < p; i++) for (let j = 0; j < p; j++) between[i]![j]! += n * prior[k]! * d[i]! * d[j]!;
