/**
 * Linear discriminant analysis (moment method). Equivalent to R's `MASS::lda()`. The moment method only. Supports matrix/group and formula/data-frame inputs.
 * Directions are metric-normalised and their signs are deterministic.
 *
 * @param x Predictor matrix.
 * @param grouping Class labels.
 * @param options Prior probabilities, tolerance, and leave-one-out CV.
 * @category Multivariate analysis
 */
export function lda(x: VectorOrMatrix, grouping: readonly GroupLabel[], options?: LdaOptions & { CV?: false }): LdaFit;
/** Leave-one-out cross-validation result overload. */
export function lda(x: VectorOrMatrix, grouping: readonly GroupLabel[], options: LdaOptions & { CV: true }): LdaCVResult;
/**
 * Linear discriminant analysis from a formula, e.g. `"class ~ x1 + x2"` or `"class ~ ."`.
 *
 * @param formula Formula.
 * @param data Data frame.
 * @param options Prior probabilities, tolerance, and leave-one-out CV.
 */
export function lda(formula: string, data: DataFrame, options?: LdaOptions & { CV?: false }): LdaFit;
export function lda(formula: string, data: DataFrame, options: LdaOptions & { CV: true }): LdaCVResult;
export function lda(x: VectorOrMatrix | string, grouping: readonly GroupLabel[] | DataFrame, options: LdaOptions = {}): LdaFit | LdaCVResult {
  checkOptions(options, LDA_KEYS, "lda"); // generated: option-keys.mjs
  if (options.method !== undefined && options.method !== "moment") throw new RangeError("only method = 'moment' is supported");
  let values: number[][], groups: GroupLabel[], names: string[];
  if (typeof x === "string") {
    const parsed = parseFormula(x);
    const response = parsed.response;
    if (!response || !Object.prototype.hasOwnProperty.call(grouping, response)) throw new RangeError("formula response must name a grouping column in data");
    const tilde = x.indexOf("~");
    if (tilde < 0) throw new SyntaxError("invalid LDA formula");
    const predictors = Object.keys(grouping as object).filter((name) => name !== response);
    const rhsText = x.slice(tilde + 1).replace(/(^|[\s+*:/()-])\.(?=$|[\s+*:/()-])/g, (_match, prefix: string) =>
      prefix + predictors.join(" + "));
    const d = design(parseFormula(`~ ${rhsText}`), grouping as DataFrame, {
      extraVariables: [response], dropUnusedLevels: false, ...(options.levels === undefined ? {} : { levels: options.levels }),
    });
    const offset = d.terms.intercept ? 1 : 0;
    const values = d.x.map((row) => row.slice(offset));
    const responseValues = Array.from((grouping as DataFrame)[response] as readonly GroupLabel[]);
    const groups = d.frame.rows.map((row) => responseValues[row]!);
    names = d.colNames.slice(offset);
    const responseVariable = d.frame.variables[d.terms.variables.length];
    const declared = options.groupLevels ?? (responseVariable?.kind === "factor" ? responseVariable.levels : undefined);
    const fit = fitCore(values, groups, options, names, declared);
    if (!options.CV) return fit;
    const classes: string[] = [];
    const posterior: number[][] = [];
    const fullPrior = fit.prior;
    for (let i = 0; i < values.length; i++) {
      const xx = values.filter((_, j) => j !== i);
      const gg = groups.filter((_, j) => j !== i);
      const sub = fitCore(xx, gg, { ...options, prior: fullPrior, CV: false }, names, declared);
      const pred = ldaPredict(sub, { newdata: [values[i]!], prior: fullPrior });
      classes.push(pred.class[0]!);
      posterior.push(pred.posterior.values[0]!);
    }
    return { class: classes, posterior: { rows: null, cols: fit._activeLev, values: posterior } };
  } else {
    values = matrixInput(x);
    groups = Array.from(grouping as readonly GroupLabel[]);
    names = options.xNames ? Array.from(options.xNames) : Array.from({ length: values[0]?.length ?? 0 }, (_, i) => `x${i + 1}`);
  }
  const fit = fitCore(values, groups, options, names, options.groupLevels);
  if (!options.CV) return fit;
  const classes: string[] = [];
  const posterior: number[][] = [];
  const fullPrior = fit.prior;
  for (let i = 0; i < values.length; i++) {
    const xx = values.filter((_, j) => j !== i);
    const gg = groups.filter((_, j) => j !== i);
    const sub = fitCore(xx, gg, { ...options, prior: fullPrior, CV: false }, names, options.groupLevels);
    const pred = ldaPredict(sub, { newdata: [values[i]!], prior: fullPrior });
    classes.push(pred.class[0]!);
    posterior.push(pred.posterior.values[0]!);
  }
  return { class: classes, posterior: { rows: null, cols: fit.lev, values: posterior } };
}

/**
 * Plug-in prediction for a fitted {@link lda} model. Equivalent to R's `predict.lda()`. The plug-in method only.
 *
 * @param fit A fitted LDA model.
 * @param options New observations, prior override, and number of discriminant scores.
 * @category Multivariate analysis
 */
export function ldaPredict(fit: LdaFit, options: LdaPredictionOptions = {}): LdaPrediction {
  checkOptions(options, LDA_PREDICT_KEYS, "ldaPredict"); // generated: option-keys.mjs
  if (options.method !== undefined && options.method !== "plug-in") throw new RangeError("only method = 'plug-in' is supported");
  const raw = options.newdata === undefined ? undefined : matrixInput(options.newdata);
  const x = raw === undefined ? fit._x : raw.map((r) =>
    r.map((v, j) => (v / fit._scale[j]! - fit._origin[j]!) / fit._spread[j]!));
  const p = fit._xNames.length;
  if (x.some((r) => r.length !== p || r.some((v) => !Number.isFinite(v)))) throw new RangeError("newdata must be a finite matrix with the fitted number of columns");
  const prior = normalisePrior(options.prior ?? fit.prior, fit.counts);
  const center = Array.from({ length: p }, (_, j) => prior.reduce((s, w, i) => s + w * fit._means[i]![j]!, 0));
  const maxDim = fit._scaling[0]?.length ?? 0;
  const dimen = options.dimen ?? maxDim;
  if (!Number.isInteger(dimen) || dimen < 1 || dimen > maxDim) throw new RangeError("dimen must be between 1 and the number of discriminant dimensions");
  const fullScores = x.map((r) => Array.from({ length: dimen }, (_, k) =>
    r.reduce((s, v, j) => s + (v - center[j]!) * fit._scaling[j]![k]!, 0)));
  const scores = fullScores.map((row) => row.slice(0, dimen));
  const meanScores = fit._means.map((mu) => Array.from({ length: dimen }, (_, k) =>
    mu.reduce((s, v, j) => s + (v - center[j]!) * fit._scaling[j]![k]!, 0)));
  const logp = fullScores.map((row) => fit._activeLev.map((_, g) => {
    let distance = 0;
    for (let k = 0; k < dimen; k++) {
      const d = row[k]! - meanScores[g]![k]!;
      distance += d * d;
    }
    return Math.log(prior[g]!) - 0.5 * distance;
  }));
  const posterior = logp.map((row) => {
    const m = Math.max(...row), ex = row.map((v) => Math.exp(v - m)), sum = ex.reduce((a, b) => a + b, 0);
    return ex.map((v) => v / sum);
  });
  return {
    class: posterior.map((r) => fit._activeLev[r.indexOf(Math.max(...r))]!),
    posterior: { rows: null, cols: fit._activeLev, values: posterior },
    x: { rows: null, cols: Array.from({ length: dimen }, (_, i) => `LD${i + 1}`), values: scores },
  };
}
